"""Domain models that are persisted to disk and returned by the API."""

from __future__ import annotations

from typing import Literal

from pydantic import BaseModel, Field

Severity = Literal["low", "medium", "high", "critical"]
SEVERITY_ORDER: dict[str, int] = {"critical": 0, "high": 1, "medium": 2, "low": 3}

DISCLAIMER = (
    "This report is an automated, informational review generated by an AI model. It is not legal advice, "
    "it may miss or misread terms, and it does not create a lawyer-client relationship. Verify every quote "
    "against the original document and consult a qualified lawyer before relying on it."
)


def format_pages(pages: list[int]) -> str:
    """[3] -> 'p. 3', [3, 4, 7] -> 'pp. 3–4, 7'."""
    if not pages:
        return "page unknown"
    pages = sorted(set(pages))
    ranges: list[str] = []
    start = prev = pages[0]
    for p in pages[1:] + [None]:  # type: ignore[list-item]
        if p is not None and p == prev + 1:
            prev = p
            continue
        ranges.append(str(start) if start == prev else f"{start}–{prev}")
        if p is not None:
            start = prev = p
    prefix = "p." if len(pages) == 1 else "pp."
    return f"{prefix} {', '.join(ranges)}"


class Chunk(BaseModel):
    id: int
    text: str
    page_start: int
    page_end: int
    section: str | None = None

    @property
    def pages(self) -> list[int]:
        return list(range(self.page_start, self.page_end + 1))

    @property
    def location(self) -> str:
        return format_pages(self.pages)

    def index_text(self) -> str:
        """Text used for retrieval: the section heading adds context to mid-section chunks."""
        return f"{self.section}\n{self.text}" if self.section else self.text


class DocumentInfo(BaseModel):
    id: str
    filename: str
    sha256: str
    page_count: int
    chunk_count: int
    char_count: int
    title: str | None = None
    empty_pages: list[int] = Field(default_factory=list)
    warnings: list[str] = Field(default_factory=list)
    embedding_model: str | None = None
    created_at: str


class Finding(BaseModel):
    id: str
    category_id: str
    category: str
    group: str
    title: str
    quote: str
    issue_type: str
    severity: Severity
    favors: str
    plain_english: str
    why_it_matters: str
    loophole_scenario: str = ""
    what_to_do: str = ""
    confidence: str = "medium"
    chunk_ids: list[int] = Field(default_factory=list)
    pages: list[int] = Field(default_factory=list)
    section: str | None = None
    verified: bool = False
    match_score: float = 0.0

    @property
    def location(self) -> str:
        return format_pages(self.pages)


class GlossaryTerm(BaseModel):
    term: str
    definition: str
    pages: list[int] = Field(default_factory=list)


class Gap(BaseModel):
    category_id: str
    category: str
    observation: str


class Party(BaseModel):
    name: str
    role: str


class ExecutiveSummary(BaseModel):
    document_type: str = ""
    parties: list[Party] = Field(default_factory=list)
    favoured_party: str = ""
    governing_law: str = ""
    what_this_document_does: str = ""
    headline: str = ""
    overall_assessment: str = ""
    top_concern_ids: list[str] = Field(default_factory=list)
    recommendations: list[str] = Field(default_factory=list)
    questions_to_ask: list[str] = Field(default_factory=list)


class RiskScore(BaseModel):
    score: int
    level: Literal["low", "moderate", "high", "severe"]
    counts: dict[str, int]
    method: str


class UsageSummary(BaseModel):
    requests: int = 0
    input_tokens: int = 0
    output_tokens: int = 0
    cache_creation_input_tokens: int = 0
    cache_read_input_tokens: int = 0
    estimated_cost_usd: float | None = None


class RetrievalStats(BaseModel):
    context_chunks: int
    total_chunks: int
    per_category: dict[str, list[int]]
    embeddings: bool


class AnalysisReport(BaseModel):
    document: DocumentInfo
    perspective: str
    jurisdiction: str | None = None
    provider: str = "anthropic"
    model: str
    effort: str | None = None
    created_at: str
    duration_seconds: float
    summary: ExecutiveSummary | None = None
    risk: RiskScore
    findings: list[Finding] = Field(default_factory=list)
    glossary: list[GlossaryTerm] = Field(default_factory=list)
    gaps: list[Gap] = Field(default_factory=list)
    retrieval: RetrievalStats
    usage: UsageSummary = Field(default_factory=UsageSummary)
    errors: list[str] = Field(default_factory=list)
    disclaimer: str = DISCLAIMER
